previewCss:
.darma-loader-darma-b16-crt-degauss { --accent: var(--loader-color, #0f766e); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .82); position: relative; }
.darma-loader-darma-b16-crt-degauss .darma-loader-darma-b16-crt-degauss__screen { position: absolute; left: 4%; right: 4%; top: 2%; height: 74%; border-radius: 14%/18%; overflow: hidden; background: radial-gradient(ellipse at 50% 45%, color-mix(in srgb, var(--accent) 62%, transparent), color-mix(in srgb, #020617 85%, transparent) 78%); box-shadow: inset 0 0 0 4px #1e293b; animation: darma-loader-darma-b16-crt-degauss-crt-pulse calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b16-crt-degauss .darma-loader-darma-b16-crt-degauss__scanlines { position: absolute; inset: 0; background: repeating-linear-gradient(color-mix(in srgb, #000 32%, transparent) 0 2px, transparent 2px 5px); }
.darma-loader-darma-b16-crt-degauss .darma-loader-darma-b16-crt-degauss__wobble { position: absolute; left: -10%; right: -10%; top: 34%; height: 26%; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-2) 65%, transparent), transparent); filter: blur(3px); animation: darma-loader-darma-b16-crt-degauss-crt-warp calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b16-crt-degauss .darma-loader-darma-b16-crt-degauss__stand { position: absolute; left: 34%; right: 34%; bottom: 2%; height: 12%; border-radius: 3px 3px 6px 6px; background: linear-gradient(#475569, #1e293b); }
@keyframes darma-loader-darma-b16-crt-degauss-crt-pulse { 0%, 100% { transform: scale(1); filter: saturate(1); } 18% { transform: scale(1.03, .96); filter: saturate(2.2); } 34% { transform: scale(.98, 1.02); filter: saturate(1.4); } 50% { transform: scale(1.01, .99); } }
@keyframes darma-loader-darma-b16-crt-degauss-crt-warp { 0%, 100% { opacity: 0; transform: translateY(60%); } 20% { opacity: .9; } 60% { opacity: .5; transform: translateY(-70%); } 70%, 100% { opacity: 0; } }

